"""Genera las ilustraciones SVG originales de la expedición Miga."""
from pathlib import Path
P = Path(__file__).resolve().parents[1] / 'www/illustrations'
P.mkdir(exist_ok=True)
robot = '''<g class="miga"><path d="M-55 0L-98-20 -106 22 -55 28M55 0L98-20 106 22 55 28" fill="#6c61bb" stroke="#b3a3ef" stroke-width="4"/><path d="M-85-13L-92 23M-70-6L-77 27M70-6L77 27M85-13L92 23" stroke="#d9c9ff" stroke-width="3"/><path d="M0-49V-72" stroke="#ffcc66" stroke-width="6"/><circle cx="0" cy="-78" r="9" fill="#ff796e"/><rect x="-49" y="-47" width="98" height="96" rx="32" fill="#ffcf6e"/><path d="M-37 25Q0 42 37 25V39Q0 63-37 39" fill="#e79743"/><rect x="-38" y="-31" width="76" height="53" rx="23" fill="#28265a"/><g class="eyes" fill="#79e5cc"><ellipse cx="-15" cy="-7" rx="7" ry="11"/><ellipse cx="15" cy="-7" rx="7" ry="11"/></g><path d="M-8 9Q0 15 8 9" fill="none" stroke="#fff0c7" stroke-width="3"/><circle cx="0" cy="35" r="5" fill="#fff0c7"/><path d="M-21 49L-28 64H28L21 49" fill="#7971b2"/><path class="thruster" d="M-15 65Q0 109 15 65" fill="#64ddc5"/></g>'''
rock = '''<path d="M-45-20L-19-43 19-39 46-12 37 26 9 42-28 30-47 6Z" fill="#b26e91"/><path d="M-45-20L-19-43 19-39 4-9-23 9-47 6Z" fill="#e49b9d"/><path d="M4-9L46-12 37 26 9 42-4 15Z" fill="#855880"/><ellipse cx="-19" cy="-12" rx="10" ry="8" fill="#ad6d8b"/><ellipse cx="18" cy="17" rx="9" ry="12" fill="#624b74"/><circle cx="15" cy="-24" r="5" fill="#f2c1af"/>'''
def stars(n,w,h):
    return ''.join(f'<circle class="star" cx="{(i*173+27)%w}" cy="{(i*97+31)%h}" r="{1+i%3}" fill="{["#fce8b8","#b8a5ef","#7adcc9"][i%3]}" style="animation-delay:-{i%7}s"/>' for i in range(n))
def svg(name,body,w=900,h=700,defs=''):
    (P/f'{name}.svg').write_text(f'<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 {w} {h}" focusable="false"><defs>{defs}</defs>{body}</svg>',encoding='utf-8')
earth='''<circle r="223" fill="#62ddc7" opacity=".09"/><circle r="207" fill="#62ddc7" opacity=".16"/><circle r="193" fill="#58d7cb"/><g clip-path="url(#earth-clip)"><circle r="180" fill="#287f9d"/><path d="M-180-100Q-80-150 30-110T185-80V-10Q80-55-30-18T-190 10Z" fill="#339db1"/><path d="M-190 90Q-100 20 0 70T200 120V200H-200Z" fill="#246883"/><g fill="#71d89c"><path d="M-163-94L-128-124-95-115-79-90-40-86-32-60-60-40-75-9-99-4-106-33-136-47-152-70Z"/><path d="M-86 7L-49 5-17 40-31 65-39 91-65 121-81 130-88 93-102 66-96 36Z"/><path d="M7-125L48-147 89-124 133-131 171-99 199-53 156-42 130-60 108-38 84-35 60-58 32-50 9-72-10-101Z"/><path d="M31-36L63-42 90-14 75 24 57 62 34 71 24 44 2 9 9-20Z"/><path d="M121 76L153 62 188 85 176 113 132 119 108 98Z"/></g><g fill="#b7edaa"><path d="M-146-93L-128-112-96-104-81-88-110-78Z"/><path d="M35-122L75-132 108-113 72-95 40-103Z"/><path d="M29-31L61-32 74-11 48 3 19-11Z"/></g><g class="clouds" fill="none" stroke="#d9f4db" stroke-width="10" stroke-linecap="round" opacity=".8"><path d="M-136-61H-75M-125-48H-98M50-87H125M74-74H153M-34 94H33M-15 107H48M-158 44H-128"/></g><path d="M87-180C189-60 115 125 9 182C158 185 212 50 177-77Z" fill="#153e74" opacity=".22"/></g>'''
svg('arrival',f'''{stars(50,900,700)}<path d="M180 520C-100 230 200 20 482 97S1032 395 710 613" fill="none" stroke="#7161a6" stroke-width="2" stroke-dasharray="5 12"/><path d="M600 0C400 70 691 138 761 290S640 540 900 600" fill="none" stroke="#504075" stroke-width="55" opacity=".45"/><g transform="translate(500 390)">{earth}</g><g class="float-slow"><g transform="translate(183 412) rotate(-14) scale(.85)">{robot}</g></g><g class="drift"><path d="M267 48L379 193 405 210 411 181Z" fill="#ee665f"/><path d="M294 80L386 192 399 187Z" fill="#ffcf6e"/><g transform="translate(400 206) scale(.65)">{rock}</g></g><g class="float-slow" style="animation-delay:-4s"><g transform="translate(756 530) rotate(34) scale(.9)">{rock}</g></g><g transform="translate(746 127) rotate(-22)"><circle r="55" fill="#f8a66d"/><path d="M-48-25Q0 0 49-25M-54-7Q0 20 55-7M-49 20Q0 45 49 20" fill="none" stroke="#df785f" stroke-width="10"/><ellipse rx="92" ry="20" fill="none" stroke="#d5a1cf" stroke-width="10"/></g><g transform="translate(250 610) scale(.35)">{rock}</g><path d="M85 191l7 17 18 7-18 7-7 18-7-18-18-7 18-7Z" fill="#ffcf6e"/><path d="M667 626l5 12 12 5-12 5-5 12-5-12-12-5 12-5Z" fill="#80dfca"/>''',defs='<clipPath id="earth-clip"><circle r="180"/></clipPath>')
svg('masses',f'''<path d="M20 209Q150 130 325 191T700 174V280H0Z" fill="#e8ddef"/><path d="M30 225H665" stroke="#bba9c8" stroke-width="2"/><g class="float-slow" transform="translate(120 130)"><g transform="scale(.45)">{rock}</g></g><g transform="translate(285 115) scale(.85)">{rock}</g><g class="float-slow"><g transform="translate(495 115) scale(1.6)">{rock}</g></g><g fill="#695486" font-family="sans-serif" font-size="14"><text x="76" y="260">Misma unidad</text><text x="435" y="260">Distintas escalas</text></g><path d="M205 185H365M353 177L365 185 353 193" stroke="#a27f9e" stroke-width="3" fill="none"/>''',700,280)
svg('archive',f'''<path d="M32 245L153 90 277 245Z" fill="#947db8"/><path d="M180 245L306 52 445 245Z" fill="#c7b3d7"/><path d="M306 52L278 95 310 87 331 99Z" fill="#fff2da"/><path d="M0 243Q210 187 470 236T700 205V290H0Z" fill="#f0b883"/><g transform="translate(487 151) scale(.85)">{robot}</g><g transform="translate(174 230) scale(.5)">{rock}</g><path d="M217 237V146H281V237" fill="#fff2da"/><path d="M229 164H269M229 178H261M229 192H267" stroke="#b17e83" stroke-width="5"/>''',700,290)
svg('method',f'''<path d="M40 144H660" stroke="#b49bca" stroke-width="4" stroke-dasharray="7 9"/><g transform="translate(115 140) scale(.85)">{robot}</g><g transform="translate(292 53)"><rect width="110" height="169" rx="18" fill="#fff4d9"/><path d="M22 37H87M22 57H76M22 77H90M22 97H80" stroke="#ad89b5" stroke-width="7"/><circle cx="84" cy="139" r="24" fill="#238b77"/><path d="M71 139L81 148 98 129" stroke="#fff4d9" stroke-width="5" fill="none"/></g><g transform="translate(527 143)"><circle r="65" fill="#f8cb69"/><circle r="38" fill="#ed9e64"/><path d="M-15 0L-1 15 26-20" stroke="#fff3d8" stroke-width="9" fill="none"/></g>''',700,280)
svg('miga',f'<g transform="translate(120 110)">{robot}</g>',240,240)
print('5 escenas SVG originales generadas')
